// file: com/shop/billing/Payments.java
package com.shop.billing;

public interface Payments {                 // the only type callers see.
    boolean charge(String customer, long cents);

    static Payments create() {              // factory hides the implementation.
        return new CardPayments(new Ledger());
    }
}

// file: com/shop/billing/CardPayments.java
package com.shop.billing;

class CardPayments implements Payments {    // package-private: invisible outside.
    private final Ledger ledger;            // private: only this class.
    CardPayments(Ledger ledger) { this.ledger = ledger; }
    public boolean charge(String customer, long cents) {
        if (cents <= 0) return false;
        ledger.record(customer, cents);
        return true;
    }
}

// file: com/shop/billing/Ledger.java
package com.shop.billing;

class Ledger {
    void record(String customer, long cents) { /* store it. */ }
}

// file: com/shop/app/Main.java  (another package)
// Payments p = Payments.create();   OK.
// new CardPayments(...)             compile error: not public.
```

| Modifier | Same class | Same package | Subclass elsewhere | Anywhere |
|---|---|---|---|---|
| private. | yes. | no. | no. | no. |
| (none). | yes. | yes. | no. | no. |
| protected. | yes. | yes. | yes. | no. |
| public. | yes. | yes. | yes. | yes. |

